          >
            <div className="mb-3 flex flex-wrap gap-3">
              <button
                type="button"
                onClick={() => setShowEqualLine((v) => !v)}
                className={`rounded-md px-3 py-1.5 text-sm font-medium ${
                  showEqualLine
                    ? "bg-slate-900 text-white"
                    : "border border-slate-200 text-slate-600"
                }`}
              >
                Equal-split line
              </button>
            </div>
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={CONCENTRATION_CURVE}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                  <YAxis
                    domain={[0, 100]}
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip
                    formatter={(v) => [fmtPct(Number(v)), ""]}
                  />
                  <Area
                    type="monotone"
                    dataKey="cumulativeVotePct"
                    fill="#0ea5e933"
                    stroke="#0ea5e9"
                    name="Cumulative IMF %"
                  />
                  {showEqualLine && (
                    <Line
                      type="monotone"
                      dataKey="equalSplitPct"
                      stroke="#94a3b8"
                      strokeDasharray="4 4"
                      dot={false}
                      name="Equal split"
                    />
                  )}
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Ranked member shares"
            subtitle="IMF / IBRD / cumulative ??? consent flag on major chairs"
          >
            <div className="mb-3">
              <ToggleGroup
                label="Metric"
                value={ladderMetric}
                onChange={setLadderMetric}
                options={[
                  { id: "imfVotePct", label: "IMF vote %" },
                  { id: "ibrdVotePct", label: "IBRD vote %" },
                  { id: "cumulativeImfPct", label: "Cumulative %" },
                ]}
              />
            </div>
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={ladderBars}>
