                  <XAxis dataKey="short" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} />
                  <Tooltip
                    formatter={(v) => [fmtPct(Number(v)), "Share"]}
                    labelFormatter={(l) => {
                      const row = VOTE_SHARES.find((m) => m.short === l);
                      const flag =
                        row?.consented16th === false
                          ? " ?? NOT consented"
                          : row?.consented16th === true
                            ? " ?? consented"
                            : "";
                      return `${l}${flag}`;
                    }}
                  />
                  <Bar dataKey="value" radius={[4, 4, 0, 0]}>
                    {ladderBars.map((r) => (
                      <Cell
                        key={r.id}
                        fill={
                          r.consented16th === false ? "#f43f5e" : r.fill
                        }
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Top-k IMF ladder"
            subtitle="Top-1 clears the 15% block line; Top-5 only reaches 40%"
          >
            <div className="h-64 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={topKBars}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                  <YAxis domain={[0, 60]} tick={{ fontSize: 11 }} />
                  <Tooltip formatter={(v) => [fmtPct(Number(v)), "IMF share"]} />
                  <Bar dataKey="value" fill="#0ea5e9" radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Regions & representation gaps"
            subtitle="Vote weight donut + vote??GDP scatter"
          >
            <div className="mb-3">
              <ToggleGroup
                label="Region"
                value={regionFilter}
                onChange={setRegionFilter}
                options={[
                  { id: "all", label: "All" },
                  { id: "Americas", label: "Americas" },
                  { id: "Europe", label: "Europe" },
                  { id: "Asia-Pacific", label: "Asia-Pac" },
                ]}
              />
            </div>
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="h-56 w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={regionDonut}
                      dataKey="value"
                      nameKey="name"
                      cx="50%"
                      cy="50%"
                      innerRadius={40}
                      outerRadius={70}
                    >
                      {regionDonut.map((r) => (
                        <Cell key={r.name} fill={r.fill} />
                      ))}
                    </Pie>
                    <Tooltip formatter={(v) => [fmtPct(Number(v)), "IMF vote"]} />
                  </PieChart>
                </ResponsiveContainer>
              </div>
              <div className="h-56 w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <ScatterChart margin={{ left: 4, right: 8 }}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis
                      type="number"
                      dataKey="x"
                      name="GDP PPP %"
                      tick={{ fontSize: 10 }}
                      unit="%"
                    />
                    <YAxis
                      type="number"
                      dataKey="y"
                      name="IMF %"
                      tick={{ fontSize: 10 }}
                      unit="%"
                    />
                    <ZAxis type="number" dataKey="z" range={[40, 200]} />
                    <Tooltip
                      formatter={(v, name) => [
                        fmtPct(Number(v)),
                        name === "x" ? "GDP PPP" : name === "y" ? "IMF vote" : "",
