"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  AS_OF,
  BLOCKING_POWER,
  CONCENTRATION_CURVE,
  CONCENTRATION_DELTAS,
  CONSENT_METERS,
  CONSENT_PATH,
  DIRIYAH_ROWS,
  GAP_SCATTER,
  HEADLINE,
  HHI_BY_LENS,
  INSTITUTION_COMPARE,
  REGION_BUCKETS,
  SCOREBOARD,
  SOURCE_NOTE,
  TOP_K_LADDER,
  VETO_SERIES,
  VOTE_SHARES,
  fmtPct,
  fmtPp,
  fmtHhi,
  fmtDays,
} from "@/data/geopolitics-institutions-concentration-202608-data";

// viz-types: HHI bars, Q3???Aug delta bars, Lorenz area+line, ranked share bars, consent+clock path lines, institution compare bars, region donut, veto stacked area, vote??GDP scatter, blocking bars, Diriyah tip-impact table | layout: default

type ViewId = "scoreboard" | "ladder" | "consent" | "power";
type LadderMetric = "imfVotePct" | "ibrdVotePct" | "cumulativeImfPct";
type CompareMetric = "top1Pct" | "top3Pct" | "top5Pct" | "hhiProxy";
type PathMode = "quota" | "nab" | "days";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function GeopoliticsInstitutionsConcentration202608Dashboard() {
  const [view, setView] = useState<ViewId>("scoreboard");
  const [ladderMetric, setLadderMetric] =
    useState<LadderMetric>("imfVotePct");
  const [compareMetric, setCompareMetric] =
    useState<CompareMetric>("top3Pct");
  const [showEqualLine, setShowEqualLine] = useState(true);
  const [regionFilter, setRegionFilter] = useState<
    "all" | "Americas" | "Europe" | "Asia-Pacific"
  >("all");
  const [pathMetric, setPathMetric] = useState<PathMode>("days");

  const ladderBars = useMemo(() => {
    return [...VOTE_SHARES]
      .map((m) => ({
        ...m,
        value:
          ladderMetric === "imfVotePct"
            ? m.imfVotePct
            : ladderMetric === "ibrdVotePct"
              ? m.ibrdVotePct
              : m.cumulativeImfPct,
      }))
      .sort((a, b) => b.value - a.value);
  }, [ladderMetric]);

  const compareBars = useMemo(
    () =>
      INSTITUTION_COMPARE.map((row) => ({
        ...row,
        value: row[compareMetric],
      })),
    [compareMetric],
  );

  const hhiBars = useMemo(
    () => [...HHI_BY_LENS].sort((a, b) => b.hhi - a.hhi),
    [],
  );

  const deltaBars = useMemo(
    () =>
      CONCENTRATION_DELTAS.map((d) => ({
        ...d,
        low: Math.min(d.prior, d.current),
        high: Math.max(d.prior, d.current),
        span: Math.abs(d.current - d.prior),
      })),
    [],
  );

  const regionDonut = useMemo(
    () =>
      REGION_BUCKETS.map((r) => ({
        name: r.short,
        value: r.imfVotePct,
        fill: r.fill,
      })),
    [],
  );

  const scatterData = useMemo(() => {
    const rows =
      regionFilter === "all"
        ? GAP_SCATTER
        : GAP_SCATTER.filter((p) => p.region === regionFilter);
    return rows.map((p) => ({
      ...p,
      x: p.gdpPppPct,
      y: p.imfVotePct,
      z: Math.max(60, Math.abs(p.gapPp) * 12),
    }));
  }, [regionFilter]);

  const pathData = useMemo(
    () =>
      CONSENT_PATH.map((p) => ({
        ...p,
        value:
          pathMetric === "quota"
            ? p.quotaPct
            : pathMetric === "nab"
              ? p.nabPct
              : p.daysToGate ?? 0,
        gate:
          pathMetric === "quota" ? 85 : pathMetric === "nab" ? 90 : null,
      })),
    [pathMetric],
  );

  const consentGapBars = useMemo(
    () =>
      CONSENT_METERS.map((m) => ({
        name: m.short,
        consented: m.consentedPct,
        gap: Math.abs(m.gapPp),
        threshold: m.thresholdPct,
        fill: m.fill,
      })),
    [],
  );

  const topKBars = useMemo(
    () =>
      TOP_K_LADDER.map((r) => ({
        ...r,
        value: r.imfSharePct,
      })),
    [],
  );

  return (
    <div
      className="space-y-6"
      data-viz="geopolitics-institutions-concentration-2026q3"
    >
