"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  AS_OF,
  BLOCKING_POWER,
  CONCENTRATION_CURVE,
  CONCENTRATION_DELTAS,
  CONSENT_METERS,
  CONSENT_PATH,
  DIRIYAH_ROWS,
  GAP_SCATTER,
  HEADLINE,
  HHI_BY_LENS,
  INSTITUTION_COMPARE,
  REGION_BUCKETS,
  SCOREBOARD,
  SOURCE_NOTE,
  TOP_K_LADDER,
  VETO_SERIES,
  VOTE_SHARES,
  fmtPct,
  fmtPp,
  fmtHhi,
  fmtDays,
} from "@/data/geopolitics-institutions-concentration-202608-data";

// viz-types: HHI bars, Q3???Aug delta bars, Lorenz area+line, ranked share bars, consent+clock path lines, institution compare bars, region donut, veto stacked area, vote??GDP scatter, blocking bars, Diriyah tip-impact table | layout: default

type ViewId = "scoreboard" | "ladder" | "consent" | "power";
type LadderMetric = "imfVotePct" | "ibrdVotePct" | "cumulativeImfPct";
type CompareMetric = "top1Pct" | "top3Pct" | "top5Pct" | "hhiProxy";
type PathMode = "quota" | "nab" | "days";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function GeopoliticsInstitutionsConcentration202608Dashboard() {
  const [view, setView] = useState<ViewId>("scoreboard");
  const [ladderMetric, setLadderMetric] =
    useState<LadderMetric>("imfVotePct");
  const [compareMetric, setCompareMetric] =
    useState<CompareMetric>("top3Pct");
  const [showEqualLine, setShowEqualLine] = useState(true);
  const [regionFilter, setRegionFilter] = useState<
    "all" | "Americas" | "Europe" | "Asia-Pacific"
  >("all");
  const [pathMetric, setPathMetric] = useState<PathMode>("days");

  const ladderBars = useMemo(() => {
    return [...VOTE_SHARES]
      .map((m) => ({
        ...m,
        value:
          ladderMetric === "imfVotePct"
            ? m.imfVotePct
            : ladderMetric === "ibrdVotePct"
              ? m.ibrdVotePct
              : m.cumulativeImfPct,
      }))
      .sort((a, b) => b.value - a.value);
  }, [ladderMetric]);

  const compareBars = useMemo(
    () =>
      INSTITUTION_COMPARE.map((row) => ({
        ...row,
        value: row[compareMetric],
      })),
    [compareMetric],
  );

  const hhiBars = useMemo(
    () => [...HHI_BY_LENS].sort((a, b) => b.hhi - a.hhi),
    [],
  );

  const deltaBars = useMemo(
    () =>
      CONCENTRATION_DELTAS.map((d) => ({
        ...d,
        low: Math.min(d.prior, d.current),
        high: Math.max(d.prior, d.current),
        span: Math.abs(d.current - d.prior),
      })),
    [],
  );

  const regionDonut = useMemo(
    () =>
      REGION_BUCKETS.map((r) => ({
        name: r.short,
        value: r.imfVotePct,
        fill: r.fill,
      })),
    [],
  );

  const scatterData = useMemo(() => {
    const rows =
      regionFilter === "all"
        ? GAP_SCATTER
        : GAP_SCATTER.filter((p) => p.region === regionFilter);
    return rows.map((p) => ({
      ...p,
      x: p.gdpPppPct,
      y: p.imfVotePct,
      z: Math.max(60, Math.abs(p.gapPp) * 12),
    }));
  }, [regionFilter]);

  const pathData = useMemo(
    () =>
      CONSENT_PATH.map((p) => ({
        ...p,
        value:
          pathMetric === "quota"
            ? p.quotaPct
            : pathMetric === "nab"
              ? p.nabPct
              : p.daysToGate ?? 0,
        gate:
          pathMetric === "quota" ? 85 : pathMetric === "nab" ? 90 : null,
      })),
    [pathMetric],
  );

  const consentGapBars = useMemo(
    () =>
      CONSENT_METERS.map((m) => ({
        name: m.short,
        consented: m.consentedPct,
        gap: Math.abs(m.gapPp),
        threshold: m.thresholdPct,
        fill: m.fill,
      })),
    [],
  );

  const topKBars = useMemo(
    () =>
      TOP_K_LADDER.map((r) => ({
        ...r,
        value: r.imfSharePct,
      })),
    [],
  );

  return (
    <div
      className="space-y-6"
      data-viz="geopolitics-institutions-concentration-202608"
    >
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 px-5 py-5 text-white shadow-sm sm:px-6">
        <p className="text-xs font-semibold uppercase tracking-wide text-sky-300">
          Institutions &amp; governance ??? August 202608 concentration lens
        </p>
        <p className="mt-2 text-lg font-bold leading-snug sm:text-xl">
          IMF Top-1 {fmtPct(HEADLINE.imfTop1Pct)} / Top-3{" "}
          {fmtPct(HEADLINE.imfTop3Pct)} still frozen ??? consent flat at{" "}
          {fmtPct(HEADLINE.quotaConsentPct, 2)} while the clock burns to{" "}
          {HEADLINE.daysRemaining} days
        </p>
        <p className="mt-2 max-w-3xl text-sm text-slate-300">
          Mid-window ({AS_OF.clockLabel}): tip ?? vs Q3 = 0 pp, consent ?? = 0 pp,
          window {fmtPct(HEADLINE.windowElapsedPct)} elapsed. US alone remains
          above the {HEADLINE.imfBlockThresholdPct}% block line and is still the
          pivotal 16th GRQ holdout ahead of {HEADLINE.consentDeadline}.
        </p>
      </div>

      <div className="flex flex-wrap items-center gap-3">
        <ToggleGroup
          label="View"
          value={view}
          onChange={setView}
          options={[
            { id: "scoreboard", label: "Scoreboard" },
            { id: "ladder", label: "Vote ladder" },
            { id: "consent", label: "Clock & consent" },
            { id: "power", label: "Block & veto" },
          ]}
        />
      </div>

      {view === "scoreboard" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Cross-perimeter HHI map"
            subtitle="Analytical concentration proxies ??? veto equality vs continuous vote weights"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={hhiBars} layout="vertical" margin={{ left: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" tick={{ fontSize: 11 }} />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={56}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v) => [fmtHhi(Number(v)), "HHI"]}
                    labelFormatter={(label) => {
                      const row = hhiBars.find((r) => r.short === label);
                      return row?.label ?? String(label);
                    }}
                  />
                  <Bar dataKey="hhi" radius={[0, 4, 4, 0]}>
                    {hhiBars.map((r) => (
                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Prior ??? Q3 concentration deltas"
            subtitle="Vote tip frozen at 0 pp; consent meters move toward the gate"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={deltaBars} layout="vertical" margin={{ left: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" tick={{ fontSize: 11 }} />
                  <YAxis
                    type="category"
                    dataKey="label"
                    width={120}
                    tick={{ fontSize: 10 }}
                  />
                  <Tooltip
                    formatter={(v, name) => [
                      typeof v === "number" ? v.toFixed(2) : String(v),
                      String(name),
                    ]}
                  />
                  <Bar dataKey="prior" fill="#94a3b8" name="Prior" radius={[0, 2, 2, 0]} />
                  <Bar dataKey="current" name="Q3" radius={[0, 2, 2, 0]}>
                    {deltaBars.map((r) => (
                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Q3 scoreboard ??? Top-1 / Top-3"
            subtitle="Four perimeters; do not average into one concentration index"
          >
            <div className="overflow-x-auto">
              <table className="w-full min-w-[28rem] text-left text-sm">
                <thead>
                  <tr className="border-b border-slate-200 text-xs uppercase text-slate-500">
                    <th className="py-2 pr-3">Perimeter</th>
                    <th className="py-2 pr-3">Top-1</th>
                    <th className="py-2 pr-3">Top-3</th>
                    <th className="py-2">Extra</th>
                  </tr>
                </thead>
                <tbody>
                  {SCOREBOARD.map((row) => (
                    <tr key={row.id} className="border-b border-slate-100">
                      <td className="py-2.5 pr-3 font-medium text-slate-800">
                        <span
                          className="mr-2 inline-block h-2.5 w-2.5 rounded-full"
                          style={{ background: row.color }}
                        />
                        {row.label}
                      </td>
                      <td className="py-2.5 pr-3 text-slate-700">
                        {fmtPct(row.top1Pct)} ?? {row.top1Label}
                      </td>
                      <td className="py-2.5 pr-3 text-slate-700">
                        {fmtPct(row.top3Pct)}
                      </td>
                      <td className="py-2.5 text-slate-500">
                        {row.extraMetric}: {row.extraValue}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </ChartCard>

          <ChartCard
            title="Institutions Top-k compare"
            subtitle="Toggle Top-1 / Top-3 / Top-5 / HHI proxy"
          >
            <div className="mb-3">
              <ToggleGroup
                label="Cut"
                value={compareMetric}
                onChange={setCompareMetric}
                options={[
                  { id: "top1Pct", label: "Top-1" },
                  { id: "top3Pct", label: "Top-3" },
                  { id: "top5Pct", label: "Top-5" },
                  { id: "hhiProxy", label: "HHI" },
                ]}
              />
            </div>
            <div className="h-64 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={compareBars}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="short" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} />
                  <Tooltip
                    formatter={(v) => [
                      compareMetric === "hhiProxy"
                        ? fmtHhi(Number(v))
